import{_ as t,o as s,c as a,a3 as i}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"CI and releases","description":"","frontmatter":{"navigation":{"category":"Repository maintenance"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/ci-and-releases.md"},"headers":[],"relativePath":"guides/ci-and-releases.md","filePath":"docs/ci-and-releases.md","lastUpdated":1791374623000}'),o={name:"guides/ci-and-releases.md"};function n(r,e,d,c,l,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="ci-and-releases" tabindex="-1">CI and releases <a class="header-anchor" href="#ci-and-releases" aria-label="Permalink to &quot;CI and releases&quot;">​</a></h1><p>The plugin and release jobs are in <code>.github/workflows/ci.yml</code>; action tests have their own <code>.github/workflows/actions.yml</code>, scoped to action code. The documentation site has its own <code>.github/workflows/docs.yml</code>, which checks and publishes the VitePress site and mirrors it to <code>gh-pages</code>. The shared setup (pnpm, Node, install, Turborepo cache) is the composite action in <code>.github/common/bootstrap</code>. Workflow jobs use <code>ubuntu-24.04</code> to keep their runner image stable as <code>ubuntu-latest</code> migrates to Ubuntu 26.</p><h2 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Job</th><th>Runs</th><th>What</th></tr></thead><tbody><tr><td>🔍 Changed files</td><td>CI-triggering changes</td><td>Separates plugin/repository code from changed action directories and documentation; detects generated README refresh commits</td></tr><tr><td>💬 Commit messages</td><td>code, action, or generated README changes on PRs</td><td>Lints every commit with <code>commitlint.config.mjs</code></td></tr><tr><td>📋 Lint</td><td>code changes</td><td><code>pnpm lint</code>: Biome, then the JSDoc check (see <a href="./code-style">Code style</a>)</td></tr><tr><td>✅ Typecheck</td><td>code changes</td><td><code>pnpm typecheck</code></td></tr><tr><td>🧪 Test</td><td>plugin or repository code changes</td><td>Package and action unit tests with V8 coverage uploaded to Codecov; project coverage may drop by up to 1 percentage point, and tests for repo scripts and agent hooks (<code>pnpm test:scripts</code>)</td></tr><tr><td>🧪 Action tests</td><td>action or shared helper code changes</td><td><code>.github/workflows/actions.yml</code> lints and tests the changed action, or <code>actions/common/</code> for shared helpers, then uploads c8 coverage to Codecov</td></tr><tr><td>📝 Docs and config</td><td>code, action, or generated README changes</td><td>Generated READMEs are current, and <code>pnpm check</code> passes: release config, package metadata, docs against the code</td></tr><tr><td>🔨 Build</td><td>code changes, after lint and typecheck</td><td>Builds and collects every plugin, then signs with <code>sign-pumpkin-plugin</code> and verifies with <code>verify-pumpkin-plugin</code> before upload</td></tr><tr><td>🎃 Integration</td><td>code changes, after build</td><td>Runs affected package suites against the pinned Pumpkin release, or the full suite for repo-level changes; reuses WASM files from the build job</td></tr><tr><td>🧬 Generator</td><td>code changes, after lint</td><td>Generates a throwaway plugin and action, checks release registration and READMEs, tests the action, then typechecks, builds and integration-tests the plugin</td></tr><tr><td>🚢 Release</td><td>plugin or action release changes, on <code>master</code> pushes</td><td>Runs release-please; action releases create a versioned tag and GitHub release without a plugin artifact</td></tr><tr><td>📝 Prepare release PR</td><td>all open release PRs on release runs</td><td>Keeps plugin READMEs, action README examples and first-release pins for plugins and actions current</td></tr><tr><td>🔏 Sign, 📎 Attach, 🛒 Market</td><td>per released plugin</td><td>Checks the tag is the commit this run built, signs and uploads the exact build artifact, publishes it to an existing Market listing, then syncs its description and commands</td></tr><tr><td>🧹 Cleanup artifacts</td><td>after successful consumers</td><td>Deletes integration and release handoff artifacts after their last use</td></tr></tbody></table><p>The signed <code>plugins</code> build artifact remains available in the run summary, with a direct download link in the build job summary, for one day. Successful runs delete the integration fixture and per-release handoff artifacts after all consumers finish. If an artifact consumer fails, cleanup is skipped so its handoff artifacts remain available for a rerun. Fork and Dependabot pull requests use read-only tokens, so their temporary artifacts expire after one day instead of being deleted by the workflow.</p><h2 id="running-only-what-a-change-needs" tabindex="-1">Running only what a change needs <a class="header-anchor" href="#running-only-what-a-change-needs" aria-label="Permalink to &quot;Running only what a change needs&quot;">​</a></h2><p><code>scripts/changed-areas.mjs</code> diffs the change against what came before it (the pull request base or the push&#39;s <code>before</code> commit). Markdown, <code>docs/</code>, component-level <code>docs/</code> folders and <code>LICENSE</code> changes are documentation. Changes under <code>actions/{name}/</code> are reported separately from plugin and repository code. An action-only change skips the plugin build, integration suites and repository test jobs; the Actions workflow tests only that action when its code changes. Action tests live beside their implementation in <code>actions/{name}/src/*.test.mjs</code>; shared helper tests live in <code>actions/common/src/*.test.mjs</code>. README, changelog and version-file-only changes skip action tests. A docs-only change triggers the separate Docs workflow, which checks the docs and builds the site; GitHub&#39;s path filters skip the main CI workflow and the Actions workflow. Mixed changes still run the relevant code or action checks.</p><p>Everything else outside <code>actions/</code> is a change to repository code and runs the code jobs, including changes under <code>tools/</code>, <code>scripts/</code> and <code>.github/</code>, and deletions. Integration tests narrow to changed plugin packages and their dependents when all code changes are within plugin or runtime-tool packages; repo-level changes run the full integration suite. Biome, the type checker and the tests read none of the documentation files, so a docs-only change cannot fail them.</p><p>The main CI <code>📝 Docs and config</code> job runs for code and action changes, and for the automatic <code>docs: update generated READMEs</code> commit. Release PRs also change version and changelog files, so GitHub continues to trigger CI as the README refresh commit is added. The classifier recognizes that commit and reruns the repository checks that validate the generated README. Ordinary docs-only PRs skip the main CI workflow entirely.</p><p>On a push, the release job waits for plugin checks when plugin/repository code changed, or for the docs/config check when only actions changed. Release Please only releases a component with releasable changes, so running it for changed action code does not create an empty release.</p><p>Know this before narrowing a job further: a skipped job takes every job that needs it with it, so no job can be gated on less than the jobs below it. Gating <code>📋 Lint</code> without <code>🔨 Build</code> would leave a release with no artifact to attach, and nothing would say so.</p><h2 id="merging" tabindex="-1">Merging <a class="header-anchor" href="#merging" aria-label="Permalink to &quot;Merging&quot;">​</a></h2><p>Pull requests are <strong>rebase-merged</strong>, never squashed. Every commit lands on <code>master</code> as written, and release-please reads each one, so every commit message must be a conventional commit: <code>feat(scope): ...</code>, <code>fix: ...</code>, <code>feat!: ...</code> for breaking changes. The commit lint enforces it.</p><p>Commits touching a plugin or its bundled workspace dependencies release that plugin. This includes transitive runtime dependencies such as <code>plugin-kit</code> and <code>update-check</code>, and the workspace build tool. A shared fix appears in each affected plugin&#39;s changelog, starting at that plugin&#39;s own last release. Tests, test helpers, generated build output and documentation do not count as shipped code. Changes to the dependency catalog or shared TypeScript configuration count for every plugin.</p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;Releases&quot;">​</a></h2><p>On <code>master</code>, once the checks pass, <a href="https://github.com/googleapis/release-please" target="_blank" rel="noreferrer">release-please</a> keeps an independent release PR up to date for each plugin or action with releasable conventional commits. Merging a plugin release PR:</p><ul><li>bumps each changed plugin&#39;s version and changelog,</li><li>tags it <code>&lt;folder&gt;-v&lt;version&gt;</code> and creates its GitHub release,</li><li>attaches <code>&lt;folder&gt;.wasm</code> and <code>&lt;folder&gt;.wasm.sha256</code>, taken from the artifact the build job made in the same run.</li></ul><p>If GitHub rejects release creation because the tag already belongs to an immutable release, the runner treats that release PR as already published and skips its artifact outputs. Other release PRs in the same run can still publish, and open release PRs are still prepared; other API errors remain failures.</p><p>Merging an action release PR updates its <code>version.txt</code> and <code>CHANGELOG.md</code>, tags it <code>&lt;folder&gt;-v&lt;version&gt;</code>, and creates a GitHub release. Action releases do not run plugin packaging, attach WebAssembly files, or publish to Pumpkin Market.</p><p>Actions import shared runtime helpers from <code>actions/common/src/</code>. Each action tag contains its own snapshot of those files, so changes to a shared helper must also include releasable changes under each consuming action directory to publish the updated helper with those actions.</p><p>The merge of a release PR is its own commit, so its push can start a run while the previous commit&#39;s run is still active. The older run may create the tag and release first, using an artifact built from the previous commit. The attach job checks that the tag points to the commit built by its run. It skips the older run&#39;s artifact, leaving the released commit&#39;s run to upload the files.</p><p>Push workflow runs are not canceled when a newer commit arrives. This lets release-please finish creating a tag and updating its release PR before the next push run reads that state. Pull request runs are still canceled when superseded.</p><p>Release Please creates a tag immediately, including while a GitHub release is a draft. Without that, a later release run can miss the previous release and recreate its changelog. The release config keeps <code>force-tag-creation</code> enabled, and the repository check enforces it.</p><p>After each Release Please run, a separate matrix job finds every open component release PR and prepares its branch, including branches Release Please did not return as changed. It regenerates plugin READMEs, generates every action README&#39;s input/output tables from its <code>action.yml</code>, and updates the versioned example tag from that action&#39;s Release Please manifest entry. For an action that has not had its first release, the README uses its <code>release-as</code> version instead of <code>0.0.0</code>. The job pushes a <code>docs: update generated READMEs</code> commit to the PR branch, so examples are current when the release merges. The same run retires the <code>release-as</code> pin of any plugin or action the PR releases (see below). release-please rewrites its branch on every update, so those commits are re-added each time.</p><p>Release PRs refresh on every release run, even when their release notes are unchanged. <code>always-update</code> keeps the remaining branches based on current <code>master</code> after another plugin&#39;s release merges, preventing conflicts in the shared manifest and release configuration. Every refreshed PR goes through the README and pin preparation job again. Separate PRs keep a plugin that is not ready from being released with one that is.</p><p>The release and release-PR preparation jobs authenticate with short-lived GitHub App installation tokens. The App is installed on this repository with <code>contents</code>, <code>issues</code> and <code>pull-requests</code> write permissions. Actions settings store its Client ID in the <code>RELEASE_APP_CLIENT_ID</code> repository variable and its private key in the <code>RELEASE_APP_PRIVATE_KEY</code> repository secret. Each job mints its own repository-scoped token; the release-PR job uses its token to push prepared README and pin updates, which trigger the normal pull-request CI checks.</p><p><code>scripts/release.mjs</code> runs the pinned Release Please runtime through <code>pnpm dlx</code>. <code>scripts/release-commits.mjs</code> supplies shared commits through its plugin hook before versions and changelogs are calculated. Features, fixes and performance improvements appear in the notes. After publishing, the runner reloads the manifest before generating PRs. Each plugin&#39;s commits stop at its own latest release, so refreshing branches does not propose an empty follow-up release. If a manifest version has no matching GitHub release or tag, the helper uses the latest published release for that plugin with a lower version as the history boundary. It fails if no such release exists or if it cannot fetch enough history, rather than publishing incomplete notes. Increase <code>commit-search-depth</code> in the release configuration if needed. Changelogs stay generated; do not edit them by hand.</p><p>To preview without changing GitHub, set <code>GITHUB_REPOSITORY</code> and <code>GITHUB_TOKEN</code>, then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --package=release-please@17.11.2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;node scripts/release.mjs --dry-run &quot;$(command -v release-please)&quot;&#39;</span></span></code></pre></div><p>Add <code>--component=&lt;name&gt;</code> to preview one plugin or action. <code>--pull-requests-only</code> updates release PRs without creating tags or GitHub releases.</p><h2 id="signing" tabindex="-1">Signing <a class="header-anchor" href="#signing" aria-label="Permalink to &quot;Signing&quot;">​</a></h2><p>Pumpkin can check a plugin&#39;s integrity: a signed <code>.wasm</code> carries two custom sections, <code>pumpkin.metadata</code> (plugin name, version, developer, issue time) and <code>wasm_signature</code> (an Ed25519 signature over the code plus the metadata, and the public key). Pumpkin loads unsigned plugins with a warning unless <code>allow_unsigned = false</code> is set in its config. Signing is optional here.</p><p><code>pnpm package</code> (<code>scripts/collect-plugins.mjs</code>) only copies built plugins into <code>dist/</code> and writes checksums; it does not sign files or warn when they are unsigned. CI always prepares a key and uses the reusable <a href="./../actions/sign-pumpkin-plugin/README"><code>sign-pumpkin-plugin</code> action</a> to sign every collected plugin from a metadata manifest. It then runs the <a href="./../actions/verify-pumpkin-plugin/README"><code>verify-pumpkin-plugin</code> action</a> against the same manifest, pinning verification to the public key derived from that run&#39;s signing key. Pushes use the repository secret when available, while pull requests and pushes without the secret use an ephemeral key. CI uses the verified signed files for integration tests. The ephemeral key is only for checks; release jobs never receive it. Release jobs use the signing action to sign the exact build artifact after checking that the release tag points to the commit that produced the build. It uploads the signed <code>.wasm</code> and refreshed <code>.sha256</code> to the GitHub release and Pumpkin Market.</p><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>Local <code>pnpm package</code></td><td>Always collects unsigned files without a warning, regardless of the key environment variable</td></tr><tr><td>CI push with a valid repository key</td><td>Signs the build and release artifacts with the repository key</td></tr><tr><td>CI pull request or push without a key</td><td>Signs build artifacts with a run-only key; release signing still requires the repository key</td></tr><tr><td>Signing action receives a malformed key</td><td>Fails rather than silently shipping unsigned files</td></tr></tbody></table><p>To set it up:</p><ol><li>Generate a key: <code>node scripts/generate-signing-key.mjs</code>. It prints a secret and a public key and writes nothing.</li><li>Settings, Secrets and variables, Actions: add the secret as the repository secret <code>PLUGIN_SIGNING_KEY</code>. The public key is safe to publish.</li></ol><p>To check a downloaded plugin: <code>node scripts/verify-plugin.mjs &lt;file.wasm&gt;</code>. It prints the plugin name, version and public key, and exits with 1 when the file is unsigned or the signature doesn&#39;t match.</p><p>The signature embeds its own public key, so Pumpkin 0.2.0 only checks that the file is intact; it doesn&#39;t know whose key it is. A server admin decides whom to trust by comparing the public key with the one you publish.</p><p>To rotate the key, generate a new one and replace the secret. Releases made with the old key stay valid, since each file carries the key it was signed with. Only the published public key changes.</p><h2 id="registering-a-plugin-for-releases" tabindex="-1">Registering a plugin for releases <a class="header-anchor" href="#registering-a-plugin-for-releases" aria-label="Permalink to &quot;Registering a plugin for releases&quot;">​</a></h2><p>A plugin is tracked only if it is listed in <strong>both</strong> release-please files. <code>pnpm gen</code> adds it to both automatically. Packages that are not ready to release can stay out of both files and be documented in <code>release-please-paused.json</code> with a reason. The release config check verifies that paused package paths exist and are not tracked. To resume a package, remove it from that file and add it to both release-please files.</p><p>Pausing an unreleased plugin also avoids the release helper&#39;s full-history scan for first releases. The plugin remains in the workspace and normal build and test workflows.</p><p>If you ever create a plugin by hand, do these three things:</p><ol><li><p>Add it to <code>release-please-config.json</code>, under <code>packages</code>. The <code>component</code> must be the folder name; it becomes the tag prefix (<code>my-plugin-v0.0.1</code>):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;packages/my-plugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;component&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-plugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;release-as&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>release-as</code> makes the first release <code>0.0.1</code> whatever the first commits are (a breaking change would otherwise make it <code>0.1.0</code>). It pins every release until it is removed, so the release job removes it from the release PR (<code>scripts/unpin-release-as.mjs</code>). That has to happen <strong>before</strong> the release PR merges, not after: <code>master</code> fails the release config check while the pin is there, and the release and attach jobs both need that check, so a release merged with the pin still in place is never tagged and gets no <code>.wasm</code>. To do it by hand, delete the line from the PR branch.</p></li><li><p>Add it to <code>.release-please-manifest.json</code>, at the same version as the plugin&#39;s <code>package.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;packages/my-plugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0&quot;</span></span></code></pre></div></li><li><p>Start the plugin at version <code>0.0.0</code> in its <code>package.json</code>. The release config also uses <code>bump-patch-for-minor-pre-major</code>, so after the first release a <code>feat</code> or <code>fix</code> bumps the patch while a plugin is below 1.0.0, and only a breaking change bumps the minor.</p></li></ol><h2 id="registering-an-action-for-releases" tabindex="-1">Registering an action for releases <a class="header-anchor" href="#registering-an-action-for-releases" aria-label="Permalink to &quot;Registering an action for releases&quot;">​</a></h2><p>Each directory under <code>actions/</code> with an <code>action.yml</code> or <code>action.yaml</code> is an independent release component. Use <code>pnpm gen:action</code> to create the standard action files and register the action. If you create one by hand, register it under <code>packages</code> in <code>release-please-config.json</code> with its folder as the component, the <code>simple</code> release strategy, and a first-release pin:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;actions/my-action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;component&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;release-type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;simple&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;release-as&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Preserve hyphens in GitHub Action input names.</strong> The runner maps <code>plugin-name</code> to the environment variable <code>INPUT_PLUGIN-NAME</code>: it uppercases input names and replaces spaces with underscores, but keeps hyphens. In JavaScript actions, import the shared <code>getInput()</code> helper from <code>actions/common/src/utils.mjs</code> and pass the input name exactly as declared, such as <code>getInput(&#39;plugin-name&#39;)</code>. Do not pass <code>PLUGIN_NAME</code> or normalize hyphens to underscores; required inputs will appear empty. Action tests must use the runner&#39;s hyphenated environment keys (for example, <code>&#39;INPUT_PLUGIN-NAME&#39;</code>) so this behavior stays covered.</p></div><p>Use a JavaScript action (<code>runs.using: node24</code>) when the implementation can run on GitHub&#39;s built-in Node runtime. Consumers do not need <code>actions/setup-node</code> or a local Node installation for that action. Use a composite action when it needs to orchestrate workflow steps or support other runner steps.</p><p>Add <code>actions/my-action/version.txt</code> with <code>0.0.0</code>, a <code>CHANGELOG.md</code>, and the same path at version <code>0.0.0</code> in <code>.release-please-manifest.json</code>. Release Please updates the version file and changelog; the repository check enforces that the action version, manifest and config stay aligned. Its tag is <code>my-action-v&lt;version&gt;</code>. The release PR job removes <code>release-as</code> after the first version is set, just as it does for plugins.</p><h2 id="repo-checks" tabindex="-1">Repo checks <a class="header-anchor" href="#repo-checks" aria-label="Permalink to &quot;Repo checks&quot;">​</a></h2><p><code>pnpm check</code> runs three scripts, each of which says exactly what is wrong. CI runs it in the <code>📝 Docs and config</code> job, and the <code>🧬 Generator</code> job runs it on a freshly generated plugin, so the generator and the checks can&#39;t drift:</p><table tabindex="0"><thead><tr><th>Script</th><th>Fails when</th></tr></thead><tbody><tr><td><code>scripts/check-release-config.mjs</code></td><td>a plugin or action is missing from either release-please file, a paused plugin is still tracked, an action is not using the <code>simple</code> strategy, <code>component</code> isn&#39;t the folder name, the manifest and package/version file disagree, an unreleased component lacks <code>release-as: 0.0.1</code>, or a released one still has it</td></tr><tr><td><code>scripts/package-metadata.mjs</code></td><td>a <code>package.json</code> lacks the license, author, contributors, homepage, repository, bugs, funding or a short description, or a library lacks <code>sideEffects</code>, <code>module</code>, <code>types</code>, <code>files</code> and <code>publishConfig</code>. <code>--fix</code> writes everything but the description</td></tr><tr><td><code>scripts/check-docs.mjs</code></td><td>a package has no README, a link, heading or path in the docs doesn&#39;t exist, a <code>pnpm</code> command isn&#39;t a script, a doc page isn&#39;t in the docs index, a root script isn&#39;t documented, or a CI job isn&#39;t in the table above</td></tr></tbody></table><p><code>pnpm test:scripts</code> runs the tests of those three, <code>scripts/unpin-release-as.mjs</code>, <code>scripts/update-action-readmes.mjs</code>, <code>scripts/changed-areas.mjs</code>, the bundled release commit selector, and the agent hooks, using fixtures and throwaway repos. See &quot;Docs match the code&quot; in <a href="./code-style">Code style</a>.</p><h2 id="publishing-to-market-pumpkinmc-org" tabindex="-1">Publishing to market.pumpkinmc.org <a class="header-anchor" href="#publishing-to-market-pumpkinmc-org" aria-label="Permalink to &quot;Publishing to market.pumpkinmc.org&quot;">​</a></h2><p>The reusable JavaScript action lives in <a href="./../actions/publish-to-pumpkin-market/README"><code>actions/publish-to-pumpkin-market/</code></a>; each action in this monorepo has its own directory, metadata and README. Other repositories can use a published version with <code>uses: filiphsps/pumpkin-plugins/actions/publish-to-pumpkin-market@publish-to-pumpkin-market-v0.0.1</code>. The action accepts the exact Pumpkin plugin name, version, <code>.wasm</code> path, optional track and release notes, a Market API token, and an optional API URL. It calls <code>PUT /api/plugins/&lt;id&gt;</code> with bearer authentication and multipart <code>wasm</code> and <code>metadata</code> fields, using the file it receives without rebuilding it. It runs directly on GitHub Actions&#39; Node 24 runtime.</p><p>In this repo, the <code>market</code> job downloads the <code>.wasm</code> produced by the build job, resolves the plugin&#39;s canonical name from its info module, and passes the per-plugin Release Please version and changelog to the action using its local path. After a successful publish, the job generates localized description and command metadata from that module and calls the metadata action with the numeric listing ID returned by the publisher. The metadata action sends a patch, so it leaves the listing&#39;s other fields to the Market listing editor. Builds aren&#39;t byte-reproducible, so the job must upload the artifact rather than rebuild.</p><p>The action looks up the canonical plugin name using PPM&#39;s flow: try the direct plugin endpoint, then search a limited result set and require an exact name match. It never creates a listing: listing metadata and review happen in Market. If the plugin is not listed, has not yet been published there, or the token is not configured, the action fails by default. Set <code>warn: true</code> to emit a warning and continue; this repository opts into that mode so GitHub releases remain independent of Market listing and credential availability. Other Market API failures always fail the job and can be retried. See the <a href="./../actions/publish-to-pumpkin-market/README#inputs">action README</a> for its complete input list. The listing metadata API and its observed behavior are documented in <a href="./pumpkin-market-api">Pumpkin Market API</a>.</p><h2 id="github-settings" tabindex="-1">GitHub settings <a class="header-anchor" href="#github-settings" aria-label="Permalink to &quot;GitHub settings&quot;">​</a></h2><p>These aren&#39;t done by the workflows:</p><ol><li>Settings, General, Pull Requests: enable <strong>Allow rebase merging</strong> only. Disable squash and merge commits.</li><li>Create and install a GitHub App on this repository with <code>contents</code>, <code>issues</code> and <code>pull-requests</code> write permissions. Add its Client ID as the <code>RELEASE_APP_CLIENT_ID</code> Actions variable and its private key as the <code>RELEASE_APP_PRIVATE_KEY</code> Actions secret. The release jobs use its installation tokens so release PRs and their updates trigger CI.</li><li>Add the Ed25519 signing key as the <code>PLUGIN_SIGNING_KEY</code> secret (see <a href="#signing">Signing</a>). Non-release checks use an ephemeral key, but the release workflow requires this secret to publish signed artifacts.</li><li>For market publishing: create a Market API key with the <code>plugins:update</code> and <code>plugins:versions:upload</code> scopes, then add it as the <code>MARKET_API_TOKEN</code> repository secret. Keep the key out of the repository and chat messages.</li><li>Optional: add the Codecov repository upload token as the <code>CODECOV_TOKEN</code> Actions secret to publish coverage from protected branches and same-repository runs. Public fork pull requests can use Codecov&#39;s tokenless upload setting. The <code>codecov.yml</code> project status compares coverage with the base commit and allows a drop of up to 1 percentage point to avoid failing on small fluctuations.</li></ol>`,61)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
